--- from: Assets/BundleResources/Prefabs/ResidentEvent/ResidentBindAccountDialog.prefab > name: ResidentBindAccountDialog
---@class UIActivityAccountBindNode
---@field Env                           	UIActivityAccountBindNode               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextTitle                     	UnityEngine.RectTransform               	@ 0    
---@field Text                          	UnityEngine.RectTransform               	@ 1    
