local UIActivityAccountBindNode = Class('UIActivityAccountBindNode')

function UIActivityAccountBindNode:__init()
    self._data = {}
    self._surveyDojo = nil        --问卷内容
    self.handler = nil
end

function UIActivityAccountBindNode:__delete()
    self.handler = nil
    self._data = nil
    self._surveyDojo = nil        --问卷内容
end

function UIActivityAccountBindNode:Awake()
    self.eventOnAppToFgCb_       = Events.AddListener(Constants.EventNames.ONAPP_TO_FG, function()
        -----@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent and checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) ~= 3 then
            --存在用户id的情况 然后再去检查是不是guest的逻辑
            GameUtils.Request("User/checkAccount", {}, function(req, resp)
                if checkNumber(resp.errCode) == 0 then
                    local data = checkTable(resp.data)
                    ---@type UserComponent
                    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                    userComponent.userInfo.isGuest = checkNumber(data.isGuest)
                    Events.Broadcast("ACCOUNT_REFRESH")
                end
            end)
        end
    end)
    self.handler = Events.AddListener("ACCOUNT_REFRESH", function()
        -----@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        if playerComponent then
            if checkNumber(playerComponent.playerDojo.openAccountUpgradeReward) == 1 and checkNumber(userComponent.userInfo.isGuest) == 0 then
                playerComponent.playerDojo.hasDrawAccountUpgradeRewards = 0
            end
        end
        ---绑定成功
        if playerComponent and checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 then
            GameUtils.SetRedPointNum(Constants.RedPointConst.AccountBindActivity, 1)
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AccountBindActivity)
        else
            GameUtils.SetRedPointNum(Constants.RedPointConst.AccountBindActivity, 0)
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AccountBindActivity)
        end
        ---剧新界面
        self:FillSelf()
    end)
    SetButtonAction(self.BtnEntry, function()
        ---@type SDKService
        local SDKService = import('Game.Entry.SDKService')
        SDKService:GetInstance():ShowUserCenter("urlPath=associatedAccount")
    end)
    SetButtonAction(self.BtnReceive, function()
        ---领取按钮状态
        self:DrawRewards()
    end)
end

function UIActivityAccountBindNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    --存在用户id的情况 然后再去检查是不是guest的逻辑
    GameUtils.Request("User/checkAccount", {}, function(req, resp)
        if checkNumber(resp.errCode) == 0 then
            local responseData = checkTable(resp.data)
            -----@type UserComponent
            local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
            if userComponent then
                userComponent.userInfo.isGuest = checkNumber(responseData.isGuest)
            end
            --CfUtils.FillText(self.Text , self._data.detail)
            self:FillSelf()
            self:RefreshContent()
            self:RefreshCurrencyBarInfo()
        end
    end)
end

function UIActivityAccountBindNode:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods()
end

function UIActivityAccountBindNode:FillSelf()
    --local startTime = self._data.startTime
    --local closeTime = self._data.closeTime
    --CfUtils.FillText(self.TextTitle, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.TextTitle, self._data.name)
    local redPoint =  self.BtnReceive.transform:Find("redPoint")
    -----@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    local isGuest = 0
    if userComponent and checkNumber(userComponent.userInfo.isGuest) == 1 then
        isGuest = 1
    --    CfUtils.SetActive(redPoint, true)
    --else
    --    CfUtils.SetActive(redPoint, false)
    end
    -----@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        CfUtils.SetActive(self.BtnEntry, checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 and isGuest == 1)
        CfUtils.SetActive(self.BtnReceive, checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 and isGuest == 0)
        CfUtils.SetActive(redPoint, checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 and isGuest == 0)
    end
end

--刷新内容
function UIActivityAccountBindNode:RefreshContent()
    -----@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        self:FillRewards(playerComponent.playerDojo.accountUpgradeRewards)
    end
end

function UIActivityAccountBindNode:DrawRewards()
    GameUtils.Request("User/drawAccountUpgradeReward", {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        -----@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComponent.playerDojo.hasDrawAccountUpgradeRewards = 3
        ---已领取状态
        if playerComponent then
            local redPoint =  self.BtnReceive.transform:Find("redPoint")
            CfUtils.SetActive(redPoint, checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 1)
        end
        CfUtils.SetActive(self.BtnReceive, false) ---已领取的情况下
        GameUtils.SetRedPointNum(Constants.RedPointConst.AccountBindActivity, 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AccountBindActivity)
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id,  -1)
        local jsonData = response.data
        if #jsonData.rewards > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })     
        else 
            GameUtils.Toast(localize("奖励已发送至邮箱"))
        end
        self:RefreshContent()
    end)
end

--奖励
function UIActivityAccountBindNode:FillRewards(rewards)
    if not rewards then
        return
    end
    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, CommonGoodsListNode)
    if not scr then
        return
    end
    scr:FreshBaseUI(rewards, false)
    -----@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent and checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 3 then
        scr:SetIsGetMaskShow(true)
    end
end

function UIActivityAccountBindNode:OnDestroy()
    if self.handler then
        Events.RemoveListener("ACCOUNT_REFRESH", self.handler)
    end
    Events.RemoveListener(Constants.EventNames.ONAPP_TO_FG, self.eventOnAppToFgCb_)
    self.eventOnAppToFgCb_ = nil
    self.handler = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityAccountBindNode
